INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l49',9,49,'Is this yours?','这是你的吗？','名词性物主代词（mine / yours / his / hers / ours / theirs） · 与形容词性物主代词对照','健身房前台失物招领','{"q":"What does Paul''s bottle look like?","options":["Blue with a logo","Black with a sticker","White and small"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l50',9,50,'Don''t push yourself','别硬撑','反身代词全表（myself / yourself / himself...） · hurt oneself · by oneself · 固定表达（Help yourself / Take care of yourself）','篮球场边，朋友扭伤脚踝','{"q":"What hurts?","options":["Andre''s hand","Andre''s ankle","Andre''s head"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l51',9,51,'I got in!','我被录取了！','just / already / yet 三兄弟综合 · already 位置（have already + 分词） · know → knew','大学录取邮件揭晓时刻（L33 的 Hailey 长大了）','{"q":"Did Hailey get in?","options":["Yes, she got in!","No, she didn''t","We don''t know"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l52',9,52,'You''ve got this!','你可以的！','too + 形容词 + for 人 / to 动词 · enough 两个位置（形容词后 / 名词前） · enough for','期末考前夜的图书馆','{"q":"When is the final?","options":["At 9 a.m.","At 2 p.m.","At midnight"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l53',9,53,'You write well!','你写得真好！','形容词 → 副词（-ly） · 形容词修饰名词 vs 副词修饰动词 · 特殊：hard / well · 陷阱：hardly','大学写作课同学互评','{"q":"What should \"He runs quick\" be?","options":["He runs quicker","He runs quickly","He quickly runs good"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l54',9,54,'Do you have a bigger size?','有大一号的吗？','比较级 -er + than · 构成规则（双写 / 直接加） · 不规则 good → better · 程度修饰 way / much','服装店买牛仔裤（L38 的 Tessa 与店员 Ray 重逢）','{"q":"The softer jeans are also ___.","options":["Tighter","Cheaper","Bigger"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l55',10,55,'More romantic or more famous?','更浪漫还是更有名？','多音节形容词比较级 more + adj · -er / more 判断规则 · way/much + more','结婚十周年选餐厅','{"q":"Which restaurant do they pick?","options":["The Harbor House","Bella Roma","Neither"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l56',10,56,'The cheapest car on the lot','全场最便宜的车','最高级 the + -est / the most · 不规则 best / worst · 范围搭配（in town / on the lot）','车行选车试驾','{"q":"The cheapest car costs ___.","options":["Nine thousand","Twelve thousand","Five thousand"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l57',10,57,'Do you have any quarters?','你有 25 美分硬币吗？','some / any 代词化（后不接名词） · none · if you have any · 美国硬币体系','街边停车咪表找零钱','{"q":"What does the meter take?","options":["Bills","Quarters","Dimes"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l58',10,58,'Somebody is at the door!','有人在敲门！','somebody / anybody / nobody / everybody 四兄弟 · 单数动词一致 · 分工同 some/any','万圣节夜，糖果失踪之谜','{"q":"Who took the candy?","options":["A kid","A dog","Nobody"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l59',10,59,'I was riding my bike when...','我正骑着车，突然……','过去进行时 was/were + V-ing · when + 一般过去式（打断） · while + 过去进行（同时） · Were you...?','办公室周一，胳膊打石膏的故事（L29 的 Molly/Raj 回归）','{"q":"What was Raj doing when the squirrel appeared?","options":["Running","Riding his bike","Driving"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l60',10,60,'Raccoon Palace','浣熊行宫','过去进行时综合叙事（背景动作 + 突发事件） · while 复现 · hear → heard · 副词体系综合运用','露营夜的怪声之谜（本课程第二篇叙述体，L50 的 Kyle/Andre 回归）','{"q":"What was making the sound?","options":["A bear","A raccoon","The wind"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l61',11,61,'A detective who never asks questions','一个从不提问的侦探','定语从句 who（修饰人） · who 作从句主语后接动词 · 从句动词单复数一致','独立书店请店员荐书','{"q":"What does Emma''s brother love?","options":["Cookbooks","Mysteries","History books"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l62',11,62,'A market that sells everything','什么都卖的市集','定语从句 which / that（修饰物） · who（人） vs which/that（物）对照 · that 从句含完整主谓','周末跳蚤市场淘货','{"q":"What does Sara want for her desk?","options":["A record","A lamp","A box"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l63',11,63,'You have to mow your lawn','你得修剪草坪','have to 深化（三态 + 三单 has to） · don''t have to（不必） vs can''t（不可以） · every two weeks / by...','新邻居收到 HOA 信件，请教社区规定（L47 的 Jonas 请教 Carlos）','{"q":"How often does Jonas have to mow the lawn?","options":["Every week","Every two weeks","Every month"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l64',11,64,'He must be a programmer','他一定是个程序员','must be + 名词/形容词/V-ing（肯定推测"一定是"） · 推测 must vs 义务 must 辨析','咖啡店"人间观察"游戏（L24 的 Rosa + L13 的 Nina）','{"q":"What does the man in the suit keep doing?","options":["Drinking coffee","Checking his watch","Reading a book"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l65',11,65,'That can''t be right!','这不可能对！','can''t be（否定推测"不可能是"） · must be ↔ can''t be 对照 · There must be a mistake. · catch → caught','公路超速被拦（Victor 倒霉三部曲终章）','{"q":"What color was the fast sports car?","options":["Black","Red","Blue"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l66',11,66,'It might rain','可能会下雨','may / might + 动词原形（不确定推测） · may not / might not · 推测三级总表（must be > may/might > can''t be）','天气不定的野餐计划（L45 的 Wendy/Dana 续集）','{"q":"What might Wendy''s sister bring?","options":["Cookies","Lemon bars","A blanket"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l67',12,67,'He said that twenty years was enough','他说二十年够了','say → said (that) + 从句 · that 可省略 · 转述人称转换 · 时态后移初识（is → was）','聊传奇球星退役新闻','{"q":"What might Marcus Cole open?","options":["A bookstore","A pizza place","A gym"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l68',12,68,'Who told you?','谁跟你说的？','tell + 人 + (that) · say vs tell 铁律（say 不接人 / tell 必接人） · told everybody','小镇消息链（Maplewood 全联动：书店搬家 + 派对改址）','{"q":"Where is the bookstore moving?","options":["The river","Main Street","The mall"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l69',12,69,'If we win, we''ll split it!','要是中了，咱们平分！','第一条件句 If + 一般现在时, will + 原形 · if 从句不用 will · What will you do if...?','加油站买彩票的白日梦（L10 的 Zoe/Ryan 回归）','{"q":"What will they do if they win?","options":["Buy a car","Split it fifty-fifty","Keep it secret"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l70',12,70,'Sorry, wrong number!','抱歉，打错了！','电话套语包（This is... / Wrong number / May I ask...?） · I''d like + 名词 · tell...that 转述落地 · ago','想订披萨却打到了牙科诊所（L39 的 Gloria 接到 L27 的 Bella）','{"q":"Where did Bella want to call?","options":["A dental office","Tony''s Pizza","A bookstore"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l71',12,71,'I had never been on a plane','我之前从没坐过飞机','过去完成时 had + 过去分词（"过去的过去"） · had never ... before · By the time..., had... · fly → flown','第一次坐飞机去大学报到（Hailey 成长线终章）','{"q":"Before today, Hailey had never been on a ___.","options":["Train","Plane","Boat"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l72',12,72,'Maplewood had never looked better','枫木镇从没这么美过','全书综合复习——八大时态 + 推测 + 定语从句 + 转述 + 条件句同框 · 第三篇叙述体（大团圆结局）','Maplewood 新河滨步道启用日，全员社区派对','{"q":"What did Maplewood open?","options":["A new bookstore","A new river trail","A new school"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',1,'Jenna','Hi! Front desk. How can I help?','珍娜：您好！这里是前台。有什么可以帮您？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',2,'Paul','Hi. I left my water bottle here yesterday. Is it in the lost and found?','保罗：你好。我昨天把水瓶落在这儿了。失物招领处有吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',3,'Jenna','Let''s see... We have three bottles. Is this blue one yours?','珍娜：我看看……这儿有三个水瓶。这个蓝色的是你的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',4,'Paul','No, that''s not mine. Mine is black with a sticker.','保罗：不，那不是我的。我的是黑色的，带贴纸。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',5,'Jenna','Hmm. This black one?','珍娜：嗯……这个黑色的？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',6,'Paul','Yes! That''s mine. Thank you!','保罗：对！就是我的。谢谢！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',7,'Jenna','Great. Oh—and is this towel yours too?','珍娜：太好了。哦——这条毛巾也是你的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',8,'Paul','No. My friend Leo was with me... Actually, that''s his. Same team logo.','保罗：不是。我朋友利奥当时和我一起……其实那是他的，同款队标。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',9,'Jenna','Got it. And these headphones?','珍娜：明白。那这副耳机呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',10,'Paul','Not ours. Sorry.','保罗：不是我们的。抱歉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',11,'Jenna','No problem. Someone will come for them—they always do.','珍娜：没关系。总会有人来认领的——一向如此。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',12,'Paul','Thanks so much. You''re the best!','保罗：太感谢了。你最棒了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',1,'Kyle','Andre! Are you okay? That fall looked bad.','凯尔：安德烈！你没事吧？刚才摔得挺重。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',2,'Andre','I''m fine, I''m fine. I hurt myself a little.','安德烈：没事没事。就伤到自己一点点。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',3,'Kyle','A little? You can''t stand up by yourself!','凯尔：一点点？你自己都站不起来！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',4,'Andre','Okay... my ankle hurts. But I can walk it off.','安德烈：好吧……脚踝疼。但我走两步就没事了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',5,'Kyle','No way. Sit down. Don''t push yourself.','凯尔：想都别想。坐下，别硬撑。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',6,'Andre','Kyle, relax. It''s just a game.','安德烈：凯尔，放松。就是打个球而已。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',7,'Kyle','Dude, last month Marcus hurt himself and played anyway. He was out for six weeks!','凯尔：哥们儿，上个月马库斯伤了还硬打，结果伤停六周！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',8,'Andre','...Fair. Okay, ice it is.','安德烈：……有道理。行，冰敷吧。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',9,'Kyle','Smart. I''ll get the first aid kit. Help yourself to my water.','凯尔：明智。我去拿急救箱。我的水你随便喝。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',10,'Andre','Thanks, man. You take care of everyone.','安德烈：谢了，兄弟。你把每个人都照顾得很好。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',11,'Kyle','Somebody has to! Now take care of yourself.','凯尔：总得有人操心！现在，照顾好你自己。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',1,'Hailey','DAD! DAD! It''s here! The email from Westfield College!','海莉：爸！爸！来了！韦斯特菲尔德学院的邮件！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',2,'Dad','Oh wow. Have you opened it yet?','爸爸：哇。你打开了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',3,'Hailey','Not yet! I''m scared. You open it!','海莉：还没！我不敢。你来打开！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',4,'Dad','No way—this is your moment. I''ve already called your mom, by the way. She''s driving home right now.','爸爸：不行——这是属于你的时刻。顺便说一句，我已经给你妈打过电话了，她正开车往家赶。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',5,'Hailey','You''ve already told Mom?! Dad!','海莉：你已经告诉妈了？！爸！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',6,'Dad','Of course! Okay, deep breath. Open it.','爸爸：当然！好了，深呼吸。打开吧。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',7,'Hailey','Okay... okay... "Dear Hailey, congratulations! We are..." I GOT IN!','海莉：好……好……"亲爱的海莉，祝贺你！我们……"我被录取了！！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',8,'Dad','YES! I knew it! I never doubted you!','爸爸：太棒了！我就知道！我从没怀疑过你！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',9,'Hailey','I''ve just read it three times. It''s real!','海莉：我刚刚连读了三遍。是真的！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',10,'Dad','Have you told your friends yet?','爸爸：告诉朋友们了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',11,'Hailey','Not yet—wait, Mom has just texted me: "SCREAMING." She already knows?!','海莉：还没——等等，妈刚给我发短信："尖叫中"。她已经知道了？！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',12,'Dad','...I texted her a photo. Sorry not sorry!','爸爸：……我把截图发给她了。抱歉，但我不后悔！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',1,'Sean','Nadia, it''s midnight. Go home. You''ve studied enough.','肖恩：娜迪亚，都半夜了。回家吧，你复习得够多了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',2,'Nadia','I can''t! The final is tomorrow, and chapter nine is too hard for me.','娜迪亚：不行！明天就期末考了，第九章对我来说太难了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',3,'Sean','It''s not too hard. You''re just too tired to think.','肖恩：不是太难，是你累得没法思考了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',4,'Nadia','Maybe. But I don''t have enough time!','娜迪亚：也许吧。但我时间不够了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',5,'Sean','You do. The test is at 2 p.m. Sleep now, review in the morning.','肖恩：够的。考试下午两点。现在睡觉，早上再过一遍。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',6,'Nadia','Is eight hours enough for chapter nine?','娜迪亚：八个小时够我啃第九章吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',7,'Sean','For you? More than enough. You''ve got this.','肖恩：对你来说？绰绰有余。你可以的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',8,'Nadia','Okay, okay. But this coffee is too cold to drink anyway.','娜迪亚：好吧好吧。反正这杯咖啡也凉得没法喝了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',9,'Sean','Ha! That''s your fourth cup. That''s enough coffee for one night.','肖恩：哈哈！那是你第四杯了。一晚上喝这么多咖啡够了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',10,'Nadia','...Fair. Pack up. Let''s go.','娜迪亚：……有道理。收拾东西，走。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',11,'Sean','Good call. See you at the final!','肖恩：明智。考场见！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',1,'Erin','Okay, Jamal. I read your essay. It''s really good!','艾琳：好了，贾马尔。我读完你的作文了。写得真不错！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',2,'Jamal','Really? Be honest. Grade it hard.','贾马尔：真的？说实话，往狠了批。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',3,'Erin','Okay... here: "He runs quick." That needs an L-Y: "quickly."','艾琳：好……这里："He runs quick."，得加 -ly："quickly"。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',4,'Jamal','Ah, right. Adverb.','贾马尔：啊对，副词。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',5,'Erin','Same here: "She sings beautiful." → "She sings beautifully."','艾琳：这儿也一样："She sings beautiful" 要改成 "beautifully"。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',6,'Jamal','Got it. Adjectives describe things, adverbs describe actions.','贾马尔：明白了。形容词描述事物，副词描述动作。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',7,'Erin','Exactly! But careful—some words don''t change. "He works hard" is correct.','艾琳：完全正确！不过小心——有些词不变形。"He works hard" 就是对的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',8,'Jamal','Not "hardly"?','贾马尔：不是 "hardly"？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',9,'Erin','No! "Hardly" means "almost not." He hardly works = he''s lazy!','艾琳：不是！"hardly" 意思是"几乎不"。He hardly works = 他很懒！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',10,'Jamal','Whoa. English is tricky.','贾马尔：哇哦。英语真难缠。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',11,'Erin','A little. But your story is great. You write well!','艾琳：有一点。不过你的故事很棒，你写得真好！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',12,'Jamal','Thanks! You explain things clearly.','贾马尔：谢谢！你讲得也特别清楚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',1,'Ray','Hey, welcome back! The sneaker lady!','雷：嘿，欢迎回来！运动鞋女士！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',2,'Tessa','Ha! That''s me. Today I need jeans.','泰莎：哈哈！正是本人。今天我要买牛仔裤。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',3,'Ray','Sure. Try these—they''re very popular.','雷：好嘞。试试这条——特别受欢迎。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',4,'Tessa','Hmm, they''re nice, but a little tight. Do you have a bigger size?','泰莎：嗯，不错，就是有点紧。有大一号的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',5,'Ray','Of course. These are bigger... and honestly, they''re softer too.','雷：当然。这条大一号……而且说实话，还更软。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',6,'Tessa','Ooh, you''re right. These feel softer. Way better!','泰莎：哦，真的。这条摸着更软，好太多了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',7,'Ray','And they''re cheaper than the first pair. Twenty bucks cheaper.','雷：而且比第一条便宜——便宜二十块。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',8,'Tessa','Cheaper AND better? Sold!','泰莎：又便宜又好？成交！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',9,'Ray','Ha! One tip: they run big. Maybe try the smaller size in black.','雷：哈哈！一个小建议：这款尺码偏大，黑色可以试小一号。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',10,'Tessa','Good call. Hmm—is the black cooler than the blue?','泰莎：好主意。嗯——黑色比蓝色更酷吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',11,'Ray','Honestly? The black is way cooler.','雷：说实话？黑色酷太多了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',12,'Tessa','Black it is. You''re better at this than me!','泰莎：那就黑色。你比我在行多了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',1,'Wes','Okay, Carla—anniversary dinner. Bella Roma or The Harbor House?','韦斯：好了，卡拉——纪念日晚餐。贝拉罗马还是海港小馆？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',2,'Carla','Ooh, tough call. Bella Roma is more romantic.','卡拉：哦，难选。贝拉罗马更浪漫。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',3,'Wes','True. But The Harbor House is more famous. The view is incredible.','韦斯：确实。但海港小馆更有名，那景色绝了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',4,'Carla','It''s also more expensive. Way more expensive.','卡拉：它也更贵。贵得多得多。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',5,'Wes','Hey, it''s our tenth anniversary! Tonight, money is not the problem.','韦斯：嘿，这可是我们十周年！今晚，钱不是问题。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',6,'Carla','Ha! Okay, big spender. Is the food better there?','卡拉：哈哈！好嘛，大款。那儿的菜更好吃吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',7,'Wes','Honestly, Bella Roma''s pasta is more delicious. But the Harbor''s seafood is fresher.','韦斯：说实话，贝拉罗马的意面更好吃。不过海港的海鲜更新鲜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',8,'Carla','Hmm. Which one is more comfortable? I want a quiet night.','卡拉：嗯。哪家更舒服？我想要个安静的夜晚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',9,'Wes','Bella Roma. The Harbor is always crowded—and louder.','韦斯：贝拉罗马。海港总是人挤人——还更吵。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',10,'Carla','Then it''s Bella Roma. Romantic, delicious, and quieter.','卡拉：那就贝拉罗马。浪漫、好吃、还更安静。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',11,'Wes','Perfect. I''ll call them right now.','韦斯：完美。我这就打电话订位。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',12,'Carla','Best husband ever.','卡拉：史上最佳老公。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',1,'Big Al','Welcome to Big Al''s Autos! I''m Big Al. What are you looking for?','大艾尔：欢迎来到大艾尔车行！我就是大艾尔。您想找什么车？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',2,'Nicole','Hi! I need a car for work. Safe, cheap, and easy to park.','妮可：你好！我要买辆通勤车。安全、便宜、好停。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',3,'Big Al','Easy! This one is the cheapest car on the lot. Nine thousand.','大艾尔：小意思！这辆是全场最便宜的，九千。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',4,'Nicole','Hmm. And the safest?','妮可：嗯。那最安全的呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',5,'Big Al','That''s this one—five stars. It''s also the most popular model this year.','大艾尔：是这辆——五星安全。它还是今年最热销的车型。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',6,'Nicole','Nice. But it''s the biggest one here. I need something smaller.','妮可：不错。但它是这儿最大的一辆，我要小一点的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',7,'Big Al','Then this blue one. Small, safe, and the newest on the lot.','大艾尔：那就这辆蓝色的。小巧、安全，还是全场最新款。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',8,'Nicole','What''s the price?','妮可：什么价？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',9,'Big Al','For you? Twelve thousand. Best price in town!','大艾尔：给您？一万二。全城最低价！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',10,'Nicole','Hmm... it''s the nicest one, honestly. Can I test-drive it?','妮可：嗯……说实话它确实是最合我意的。能试驾吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',11,'Big Al','Of course! Here are the keys. Worst case, you get a fun ride!','大艾尔：当然！钥匙给您。大不了，就当兜个风！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',12,'Nicole','Ha! Let''s go.','妮可：哈哈！走起。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',1,'Jamal','Oh no. This meter only takes quarters.','贾马尔：糟了。这咪表只收 25 美分硬币。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',2,'Jamal','Excuse me! Do you have any quarters?','贾马尔：打扰一下！您有 25 美分硬币吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',3,'Grace','Let me check my purse... Hmm, I don''t think I have any.','格蕾丝：我看看包……嗯，好像一个也没有。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',4,'Jamal','No worries. Thanks anyway.','贾马尔：没关系。还是谢谢您。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',5,'Grace','Wait—there are some coins in my car. One second.','格蕾丝：等等——我车里有些硬币。稍等。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',6,'Grace','Okay: dimes, nickels... and quarters! How many do you need?','格蕾丝：来了：10 美分的、5 美分的……还有 25 美分的！你要几个？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',7,'Jamal','Two, if you have any.','贾马尔：两个，如果您有的话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',8,'Grace','I have three. Take them all.','格蕾丝：我有三个。都拿去吧。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',9,'Jamal','You''re a lifesaver! Here—I have some bills. Let me pay you back.','贾马尔：您真是救星！这儿——我有纸币，我还您钱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',10,'Grace','No need. It''s seventy-five cents!','格蕾丝：不用啦。总共七毛五！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',11,'Jamal','Ha! Okay. Well—none of my friends are this nice.','贾马尔：哈哈！好吧。说真的——我朋友里都没这么好心的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',12,'Grace','Pay it forward! Have a good one!','格蕾丝：把善意传下去就行！祝愉快！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',1,'Faith','Derek! Somebody is at the door again!','费丝：德里克！又有人在门口！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',2,'Derek','Coming! ...Nobody''s here. Just a pumpkin on the steps.','德里克：来了！……没人啊。台阶上就一个南瓜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',3,'Faith','Weird. That''s the third time tonight.','费丝：怪了。今晚第三次了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',4,'Derek','Wait—did anybody take candy from the bowl?','德里克：等等——有人从糖果碗里拿糖了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',5,'Faith','Let me see... The bowl is empty! Somebody took everything!','费丝：我看看……碗空了！有人把糖全拿走了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',6,'Derek','No way. Okay, everybody stay calm. I''ll check the camera.','德里克：不会吧。好，大家保持冷静。我去看监控。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',7,'Faith','"Everybody"? It''s just us, Derek.','费丝："大家"？就咱俩，德里克。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',8,'Derek','...Okay, both of us stay calm. Look—the camera!','德里克：……好吧，咱俩保持冷静。看——监控！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',9,'Faith','Is that... a dog? A dog in a dinosaur costume?!','费丝：那是……一只狗？穿恐龙服的狗？！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',10,'Derek','Ha! The Hendersons'' dog! He took the whole bowl!','德里克：哈哈！亨德森家的狗！它把一整碗都端走了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',11,'Faith','Nobody will believe this. Send the video to everybody!','费丝：没人会信的。把视频发给所有人！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',12,'Derek','Best Halloween ever.','德里克：史上最棒万圣节。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',1,'Molly','Raj, why is your arm in a cast?!','莫莉：拉杰，你胳膊怎么打上石膏了？！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',2,'Raj','Funny story. I was riding my bike when a squirrel ran into the road.','拉杰：说来好笑。我正骑着车，一只松鼠突然窜上了路。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',3,'Molly','A squirrel?!','莫莉：松鼠？！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',4,'Raj','Yep. I was going downhill, so I turned fast... and met a tree.','拉杰：对。当时正下坡，我猛一转弯……跟一棵树来了个会面。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',5,'Molly','Oh no! Were you wearing a helmet?','莫莉：天哪！你当时戴头盔了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',6,'Raj','I was! Safety first. The helmet is fine. My arm... less fine.','拉杰：戴了！安全第一。头盔没事。胳膊……不太没事。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',7,'Molly','What happened to the squirrel?','莫莉：那松鼠呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',8,'Raj','Oh, he was totally fine. He was eating an acorn while I was lying on the ground.','拉杰：哦，它好得很。我躺在地上的时候，它在旁边吃橡果。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',9,'Molly','Ha! Rude.','莫莉：哈哈！太没礼貌了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',10,'Raj','Right? Anyway, six weeks in a cast. No biking.','拉杰：可不是嘛。总之，石膏六周，不许骑车。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',11,'Molly','Well—while you were breaking your arm, I was running my first 5K!','莫莉：嗯——你摔胳膊的时候，我跑完了人生第一个五公里！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',12,'Raj','No way! Molly! Okay, that''s the best news today.','拉杰：不会吧！莫莉！好，这是今天最棒的消息。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',1,NULL,'Last month, Kyle and Andre went camping at Bear Lake.','上个月，凯尔和安德烈去熊湖露营。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',2,NULL,'On the first night, they were sitting by the fire and telling stories.','第一晚，他们正坐在篝火旁讲故事。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',3,NULL,'Suddenly, they heard a strange sound in the trees.','突然，他们听到树林里有奇怪的声响。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',4,NULL,'"Shh! Did you hear that?" Kyle whispered.','"嘘！你听到了吗？"凯尔低声说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',5,NULL,'Something was moving behind their tent.','有什么东西正在帐篷后面移动。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',6,NULL,'Andre grabbed his flashlight, but his hands were shaking.','安德烈抓起手电筒，但他的手在发抖。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',7,NULL,'While Kyle was looking for his phone, the sound came closer... and closer.','凯尔翻找手机的时候，那声音越来越近……越来越近。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',8,NULL,'Then Andre turned on the light. Nobody was there—just a fat raccoon!','然后安德烈打开了灯。没有人——只有一只肥浣熊！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',9,NULL,'It was eating their marshmallows and looking right at them.','它正吃着他们的棉花糖，还直勾勾地盯着他们。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',10,NULL,'The raccoon finished the whole bag and walked away slowly, like a boss.','浣熊吃完了一整袋，然后慢悠悠地走了，像个大佬。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',11,NULL,'Kyle and Andre laughed for ten minutes. Now they call that campsite "Raccoon Palace."','凯尔和安德烈笑了十分钟。现在他们管那个营地叫"浣熊行宫"。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',1,'Ruth','Welcome to Page Turner Books! Looking for anything special?','露丝：欢迎来到"翻不停"书店！想找什么特别的书吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',2,'Emma','Yes! I need a gift for my brother. He''s someone who reads everything.','艾玛：对！我要给我哥挑份礼物。他是个什么都读的人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',3,'Ruth','Nice. What does he like?','露丝：真好。他喜欢什么类型？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',4,'Emma','Mysteries. He loves writers who build slow, smart stories.','艾玛：悬疑。他喜欢那种慢慢铺陈、构思聪明的作家。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',5,'Ruth','Then he''ll love this one. It''s about a detective who never asks questions.','露丝：那他一定会爱这本。讲的是一个从不提问的侦探。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',6,'Emma','A detective who never asks questions? How does that work?','艾玛：从不提问的侦探？那案子怎么破？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',7,'Ruth','Ha! That''s the mystery! People who read it can''t stop talking about it.','露丝：哈哈！这就是悬念所在！读过的人都停不下来地讨论它。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',8,'Emma','Sold! And something for my mom? She''s a person who cooks a lot.','艾玛：成交！再给我妈挑一本？她是个特别爱做饭的人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',9,'Ruth','Easy—this cookbook. The chef who wrote it has a diner in Texas.','露丝：简单——这本菜谱。写它的大厨在得州开了家小餐馆。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',10,'Emma','Perfect. You''re a bookseller who really knows books!','艾玛：完美。你真是个懂书的书店店员！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',11,'Ruth','Ha! That''s the nicest thing a customer said all week.','露丝：哈哈！这是本周顾客对我说过的最好听的话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',1,'Jake','Sara, look at this place! A market that sells everything!','杰克：萨拉，看看这地方！一个什么都卖的市集！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',2,'Sara','I know! Okay—I want a lamp that matches my new desk.','萨拉：可不是！好——我要找一盏配得上我新书桌的台灯。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',3,'Jake','There''s a table over there which has old lamps. Green ones, gold ones...','杰克：那边有张桌子摆着旧台灯。绿的、金的……') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',4,'Sara','Ooh! And look—a box that is full of old books!','萨拉：哦！你看——一箱子全是旧书！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',5,'Jake','Of course you found the books. Classic Sara.','杰克：你果然直奔书去了。太萨拉了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',6,'Sara','This one is a mystery which was famous in the 1960s. Two bucks!','萨拉：这本是六十年代很有名的悬疑小说。才两块！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',7,'Jake','Nice find! I want a jacket that looks cool but costs nothing.','杰克：好眼力！我想找一件看着酷但不要钱的夹克。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',8,'Sara','Ha! Good luck. Oh—that stand has records which are only a dollar!','萨拉：哈哈！祝你好运。哦——那个摊的黑胶唱片只要一块钱！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',9,'Jake','Whoa. Okay, this is a place that we need to visit every weekend.','杰克：哇哦。行，这地方咱们得每周末都来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',10,'Sara','Deal. But first—help me carry this lamp that I just bought.','萨拉：成交。不过先——帮我搬一下我刚买的这盏台灯。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',11,'Jake','...It''s heavy, isn''t it?','杰克：……很沉，对吧？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',12,'Sara','Some things never change!','萨拉：有些事永远不会变！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',1,'Jonas','Carlos! Quick question. I got a letter from the HOA... What''s an HOA?','乔纳斯：卡洛斯！问个小问题。我收到一封 HOA 的信……HOA 是什么？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',2,'Carlos','Ha! Welcome to the neighborhood. It''s the homeowners association. They have rules.','卡洛斯：哈哈！欢迎来到咱们社区。那是业主协会，他们有一堆规定。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',3,'Jonas','Rules? Like what?','乔纳斯：规定？比如？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',4,'Carlos','Well, you have to mow your lawn every two weeks.','卡洛斯：嗯，你每两周得修剪一次草坪。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',5,'Jonas','Every two weeks?! I fly to Tokyo every two weeks!','乔纳斯：每两周？！我每两周还得飞一趟东京呢！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',6,'Carlos','Ha! Then you have to hire somebody. My guy is cheap—I''ll send you his number.','卡洛斯：哈哈！那你得雇个人。我认识的师傅便宜——我把号码发你。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',7,'Jonas','Thanks. Anything else I have to do?','乔纳斯：谢了。还有什么必须做的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',8,'Carlos','You have to put the trash cans away by Friday night. And you can''t paint your door purple.','卡洛斯：垃圾桶周五晚上前得收回去。还有，门不能刷成紫色。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',9,'Jonas','Purple? Who paints a door purple?','乔纳斯：紫色？谁会把门刷成紫色？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',10,'Carlos','The Hendersons did. Once. There was a meeting.','卡洛斯：亨德森家干过。就一次。后来开了个会。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',11,'Jonas','Ha! Okay. Do I have to go to the meetings?','乔纳斯：哈哈！好吧。会议我必须参加吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',12,'Carlos','You don''t have to. But there are free cookies.','卡洛斯：不必。不过有免费饼干。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',1,'Nina','Rosa, look at that guy by the window. Three laptops!','妮娜：罗莎，看窗边那个人。三台笔记本电脑！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',2,'Rosa','Three?! He must be a programmer.','罗莎：三台？！他一定是个程序员。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',3,'Nina','Or a spy.','妮娜：也可能是间谍。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',4,'Rosa','Ha! And that woman with all the books? She must be a student. Finals week.','罗莎：哈哈！那个抱着一摞书的女士呢？她一定是学生。期末周嘛。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',5,'Nina','She must be so tired. That''s her third coffee.','妮娜：她一定累坏了。那是她第三杯咖啡了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',6,'Rosa','Been there.','罗莎：我懂，经历过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',7,'Nina','Ooh—and the man in the suit? He keeps checking his watch.','妮娜：哦——那个穿西装的男士呢？他一直在看表。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',8,'Rosa','He must be waiting for someone. A big meeting, maybe.','罗莎：他一定在等人。也许是个重要会议。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',9,'Nina','Or a first date! Look—flowers under the table!','妮娜：也可能是初次约会！看——桌子底下有花！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',10,'Rosa','No way! You''re right. He must be so nervous.','罗莎：不会吧！你说对了。他一定紧张死了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',11,'Nina','Aww. Okay, new game: guess everybody''s story.','妮娜：可爱。好，新游戏：猜每个人的故事。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',12,'Rosa','Ha! We must be the nosiest people in this coffee shop.','罗莎：哈哈！我们一定是这家咖啡店里最爱管闲事的人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',1,'Officer','Good afternoon. License, please. Sir, you were going seventy-five.','警官：下午好。请出示驾照。先生，您刚才时速七十五。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',2,'Victor','Seventy-five?! That can''t be right! This car can''t even go that fast!','维克多：七十五？！这不可能对！我这车根本跑不了那么快！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',3,'Officer','The radar says it can.','警官：雷达说它可以。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',4,'Victor','Officer, there must be a mistake. Maybe the radar caught that red sports car!','维克多：警官，这一定是搞错了。也许雷达测到的是那辆红色跑车！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',5,'Officer','Hmm. A red sports car?','警官：嗯？红色跑车？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',6,'Victor','Yes! It passed me like I was standing still!','维克多：对！它超我的时候，我就跟静止了一样！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',7,'Officer','...Actually, you can''t be wrong. My partner just stopped a red sports car up the road.','警官：……还真是，你不可能说错。我搭档刚在前面拦下一辆红色跑车。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',8,'Victor','See! It must be that guy!','维克多：看吧！一定是那家伙！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',9,'Officer','You''re free to go, sir. But hey—your left light is out. You have to fix it this week.','警官：您可以走了，先生。不过——您左边车灯坏了，这周得修好。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',10,'Victor','Of course it is. Sir, I must be the unluckiest driver in this town.','维克多：果然又坏了。警官，我一定是全城最倒霉的司机。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',11,'Officer','Ha! Drive safe.','警官：哈哈！注意行车安全。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',12,'Victor','Always. Well... mostly.','维克多：一向如此。呃……大部分时候。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',1,'Dana','Wendy! Still on for the picnic Saturday?','达娜：温蒂！周六野餐还照旧吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',2,'Wendy','Maybe... The weather app says it might rain.','温蒂：不好说……天气 App 说可能下雨。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',3,'Dana','Might? Or will?','达娜：可能？还是一定？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',4,'Wendy','Sixty percent. So it may rain, or it may not. Classic spring.','温蒂：百分之六十。可能下，也可能不下。典型的春天。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',5,'Dana','Okay, plan B. We might move it to Sunday.','达娜：好，B 计划。我们也许挪到周日。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',6,'Wendy','Sunday works for me. But my sister may come too—is that okay?','温蒂：周日我可以。不过我妹妹可能也来——没问题吧？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',7,'Dana','Of course! The more, the merrier.','达娜：当然！人越多越热闹。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',8,'Wendy','Ha! She might bring her famous lemon bars.','温蒂：哈哈！她可能会带她的招牌柠檬方块。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',9,'Dana','Then she HAS to come. No "might" about it!','达娜：那她必须来。没有"可能"这一说！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',10,'Wendy','Ha! Okay. And if it rains on Sunday too?','温蒂：哈哈！好。那要是周日也下雨呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',11,'Dana','Then we may just have a picnic in my living room. Blanket and all!','达娜：那我们就干脆在我家客厅野餐。连毯子都铺上！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',12,'Wendy','It''s a plan. Rain or shine!','温蒂：就这么定了。风雨无阻！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',1,'Ken','Lauren! Did you see the news? Marcus Cole is retiring!','肯：劳伦！看新闻了吗？马库斯·科尔要退役了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',2,'Lauren','The quarterback? No way! What did he say?','劳伦：那个四分卫？不会吧！他说什么了？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',3,'Ken','He said that twenty years was enough.','肯：他说二十年够了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',4,'Lauren','Wow. Twenty years. What else?','劳伦：哇，整整二十年。还说什么了？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',5,'Ken','He said he wants more time with his kids.','肯：他说他想多陪陪孩子。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',6,'Lauren','Aww. That''s sweet. And his plans?','劳伦：太暖了。那他有什么打算？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',7,'Ken','He said that he might open a pizza place.','肯：他说他可能开一家披萨店。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',8,'Lauren','A pizza place?! I love that. What did his coach say?','劳伦：披萨店？！我爱了。他教练怎么说？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',9,'Ken','The coach said Marcus was the hardest worker on the team.','肯：教练说马库斯是队里最拼的人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',10,'Lauren','True. My dad always said, "Watch number 12—he never quits."','劳伦：确实。我爸总说："盯住 12 号——他从不放弃。"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',11,'Ken','Ha! Well, number 12 said thank you and goodbye.','肯：哈哈！现在，12 号说了声谢谢和再见。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',12,'Lauren','End of an era. Okay—pizza place field trip when it opens?','劳伦：一个时代结束了。好——店开业了咱们组团去？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',1,'Priya','Megan! Big Maplewood news. Did you hear?','普丽娅：梅根！枫木镇大新闻。你听说了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',2,'Megan','No! Tell me everything.','梅根：没有！快全告诉我。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',3,'Priya','Ruth told me that the bookstore is moving to Main Street!','普丽娅：露丝跟我说，书店要搬到主街上了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',4,'Megan','The bookstore?! That''s huge. Who told you?','梅根：书店？！这可是大事。谁跟你说的？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',5,'Priya','Ruth herself. And she told me they will have a coffee corner.','普丽娅：露丝本人。她还跟我说店里会开个咖啡角。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',6,'Megan','Books AND coffee? Take my money.','梅根：书加咖啡？快收下我的钱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',7,'Priya','Ha! Also—Carlos told me that the block party is moving to the new trail.','普丽娅：哈哈！还有——卡洛斯跟我说，街区派对要挪到新步道那边办了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',8,'Megan','The new trail by the river? Perfect.','梅根：河边那条新步道？完美。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',9,'Priya','Yep. And Jonas told everybody that he will bring pizza from Tony''s.','普丽娅：对。乔纳斯还跟大家说，他会从托尼家带披萨来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',10,'Megan','This town, honestly. Everybody knows everything in two hours.','梅根：这镇子啊，说真的。任何事两小时内人尽皆知。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',11,'Priya','Ha! Don''t say that—YOU told ME about the Hendersons'' dog!','普丽娅：哈哈！你可别这么说——亨德森家狗的事就是你告诉我的！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',12,'Megan','...Fair. See you at the trail!','梅根：……有道理。步道见！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',1,'Ryan','Zoe, look—the jackpot is 400 million!','瑞安：佐伊，你看——头奖四个亿！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',2,'Zoe','Whoa. Okay, two tickets. If we win, we''ll split it fifty-fifty.','佐伊：哇哦。行，买两张。要是中了，咱们五五分。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',3,'Ryan','Deal. So—what will you do if you win?','瑞安：成交。那——要是你中了，你打算干什么？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',4,'Zoe','Easy. If I win, I''ll quit my job... politely.','佐伊：简单。中了我就辞职……礼貌地辞。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',5,'Ryan','Ha! And then?','瑞安：哈哈！然后呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',6,'Zoe','I''ll buy a beach house. And if my sister asks, I''ll buy her one too.','佐伊：买栋海景房。要是我妹开口，也给她买一栋。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',7,'Ryan','Generous! If I win, I''ll travel for a whole year.','瑞安：大方！要是我中了，我要旅行整整一年。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',8,'Zoe','Where will you go first?','佐伊：先去哪儿？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',9,'Ryan','Japan. And if the money is still there after that, Italy.','瑞安：日本。之后钱要是还没花完，就去意大利。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',10,'Zoe','Smart. Okay, real talk: if we don''t win, we''ll still get tacos tonight?','佐伊：明智。好，说正经的：要是没中，今晚照样吃塔可吧？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',11,'Ryan','Obviously. Win or lose, taco night is taco night.','瑞安：那当然。无论输赢，塔可之夜就是塔可之夜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',12,'Zoe','That''s why we''re friends.','佐伊：所以咱俩才是朋友。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',1,'Gloria','Lakeside Dental, this is Gloria.','格洛丽亚：湖畔牙科，我是格洛丽亚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',2,'Bella','Hi! I''d like a large pepperoni pizza, extra cheese.','贝拉：你好！我要一份大份辣香肠披萨，加倍芝士。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',3,'Gloria','Ma''am... this is a dental office.','格洛丽亚：女士……这里是牙科诊所。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',4,'Bella','Oh no. I''m so sorry! Wrong number!','贝拉：天哪。太抱歉了！打错了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',5,'Gloria','Ha! No worries. It happens every week—we''re one digit from Tony''s Pizza.','格洛丽亚：哈哈！没关系。每周都有——我们和托尼披萨就差一位数。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',6,'Bella','Wait, really? That''s hilarious.','贝拉：等等，真的？太好笑了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',7,'Gloria','Yep. Actually, while you''re here—may I ask, when was your last cleaning?','格洛丽亚：真的。话说，既然您都打来了——冒昧问一句，您上次洗牙是什么时候？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',8,'Bella','My last...? Oh. Um. Two years ago?','贝拉：上次……？呃。嗯。两年前？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',9,'Gloria','Mm-hmm. Can I schedule you for Tuesday? Dr. Kim has an opening.','格洛丽亚：嗯哼。我给您约周二好吗？金医生正好有空档。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',10,'Bella','You know what? Sure. Book it. Best wrong number ever.','贝拉：您猜怎么着？行。就这么订。史上最佳打错电话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',11,'Gloria','Perfect! I''ll tell Dr. Kim that you''re coming. And Bella—Tony''s is 555-0198.','格洛丽亚：完美！我会告诉金医生您要来。对了贝拉——托尼家的号码是 555-0198。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',12,'Bella','Ha! You''re the best. Pizza first, teeth Tuesday!','贝拉：哈哈！你最棒了。今晚披萨，周二看牙！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',1,'Dorothy','First flight, sweetie? Your hands are shaking a little.','多萝西：第一次坐飞机吧，孩子？你的手有点抖。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',2,'Hailey','Is it that obvious? Yes. Before today, I had never been on a plane.','海莉：这么明显吗？是的。在今天之前，我从没坐过飞机。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',3,'Dorothy','Aww. Where are you headed?','多萝西：真可爱。你这是去哪儿？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',4,'Hailey','Westfield College! Move-in day is tomorrow.','海莉：韦斯特菲尔德学院！明天就是入住报到日。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',5,'Dorothy','College! How exciting. You know, I had never flown before my fortieth birthday.','多萝西：上大学！多让人激动。你知道吗，我四十岁生日之前从没坐过飞机。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',6,'Hailey','Really? Never?','海莉：真的？从没有？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',7,'Dorothy','Never. I had lived in the same small town my whole life. Then one day, I bought a ticket to Paris.','多萝西：从没有。我一辈子都住在同一个小镇。然后有一天，我买了张去巴黎的机票。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',8,'Hailey','Paris?! Just like that?','海莉：巴黎？！说走就走？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',9,'Dorothy','Just like that. By the time I came home, I had visited nine countries.','多萝西：说走就走。等我回到家的时候，我已经去过九个国家了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',10,'Hailey','Whoa. That''s the dream.','海莉：哇哦。这就是梦想生活。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',11,'Dorothy','So don''t be nervous, sweetie. Every big life starts with one scary first step.','多萝西：所以别紧张，孩子。每一段精彩人生，都始于一次令人害怕的第一步。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',12,'Hailey','...Okay. Okay! First flight, here we go.','海莉：……好。好！第一次飞行，出发！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',1,NULL,'On the first Saturday of June, Maplewood opened its new river trail.','六月的第一个周六，枫木镇的新河滨步道正式启用。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',2,NULL,'Everybody who lived in town came to the party.','镇上的每一个人都来参加了庆祝派对。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',3,NULL,'Carlos and Megan had planned the day for months, and it was perfect.','卡洛斯和梅根为这一天筹备了好几个月，一切完美。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',4,NULL,'Jonas brought pizza from Tony''s, and Megan''s lemonade went fast—as always.','乔纳斯从托尼家带来了披萨，梅根的柠檬水一如既往地被抢光。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',5,NULL,'Rosa and Nina were guessing everybody''s story by the coffee stand.','罗莎和妮娜在咖啡摊边玩着"猜人生"的游戏。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',6,NULL,'"That runner must be training for a race," Rosa said.','"那个跑步的人一定在备赛，"罗莎说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',7,NULL,'She was right—it was Molly, who has run three 5Ks since spring.','她猜对了——那是莫莉，开春以来她已经跑完了三个五公里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',8,NULL,'Victor arrived late, of course. "My car didn''t start," he told everybody. Nobody was surprised.','维克多照例迟到了。"我的车没打着火，"他跟大家说。没有人感到意外。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',9,NULL,'Kyle and Andre told the raccoon story again, and it got funnier every time.','凯尔和安德烈又讲了一遍浣熊的故事，每讲一次都更好笑。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',10,NULL,'"If the weather stays nice, we''ll do this every month," Carlos said.','"如果天气一直这么好，我们每个月都办一次，"卡洛斯说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',11,NULL,'Hailey, home from college, took photos of everything. "I had never seen the whole town in one place," she said.','从大学回家的海莉拍下了一切。"我从没见过全镇的人聚在同一个地方，"她说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',12,NULL,'The sun went down slowly over the river. Maplewood had never looked better.','夕阳缓缓沉入河面。枫木镇从没这么美过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
