INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l53_gp1','am1_l53','-ly 副词构成与分工','**① 形容词 → 副词：加 -ly**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l53_gp2','am1_l53','hard / well 特殊与 hardly 陷阱','**① 形容词 → 副词：加 -ly**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l54_gp1','am1_l54','比较级构成（-er / 双写 / better）','**① 比较级 -er + than**：These are **cheaper than** the first pair. / Is the black **cooler than** the blue?
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l54_gp2','am1_l54','than 与程度修饰','**① 比较级 -er + than**：These are **cheaper than** the first pair. / Is the black **cooler than** the blue?
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l55_gp1','am1_l55','more + 多音节比较级','**① 多音节形容词比较级：more + 形容词**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l55_gp2','am1_l55','-er / more 判断规则','**① 多音节形容词比较级：more + 形容词**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l56_gp1','am1_l56','最高级构成（the -est / the most）','**① 最高级：the + -est**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l56_gp2','am1_l56','best / worst 与范围搭配','**① 最高级：the + -est**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l57_gp1','am1_l57','some / any 代词化','**① some / any 代词化（后面不接名词）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l57_gp2','am1_l57','none','**① some / any 代词化（后面不接名词）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l58_gp1','am1_l58','somebody / anybody / nobody / everybody 分工','**① 四兄弟分工（同 some/any 规则）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l58_gp2','am1_l58','单数动词一致','**① 四兄弟分工（同 some/any 规则）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l59_gp1','am1_l59','过去进行时构成','**① 过去进行时：was/were + V-ing（过去某刻正在进行）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l59_gp2','am1_l59','when / while','**① 过去进行时：was/were + V-ing（过去某刻正在进行）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l60_gp1','am1_l60','过去进行综合叙事','**① 过去进行时综合叙事：背景动作**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l60_gp2','am1_l60','heard 与副词复现','**① 过去进行时综合叙事：背景动作**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l61_gp1','am1_l61','定语从句 who','**① 定语从句 who（修饰人："……的人"）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l61_gp2','am1_l61','从句动词单复数一致','**① 定语从句 who（修饰人："……的人"）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l62_gp1','am1_l62','which / that 修饰物','**① 定语从句 which / that（修饰物："……的东西"）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l62_gp2','am1_l62','who vs which/that 辨析','**① 定语从句 which / that（修饰物："……的东西"）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l63_gp1','am1_l63','have to 三态与三单','**① have to 三态深化**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l63_gp2','am1_l63','don''t have to vs can''t 辨析','**① have to 三态深化**
