INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l64_gp2','am1_l64','推测 must vs 义务 must 辨析','**① must be + 名词（一定是……）**：He **must be a programmer**. / She **must be a student**.
